package com.hpe.morpheus.harvester.plugin.apihelper

import com.hpe.morpheus.harvester.plugin.utils.HarvesterConstants
import com.hpe.morpheus.harvester.plugin.utils.parsers.CommonParser
import com.morpheusdata.model.ComputeServerGroup
import com.morpheusdata.response.ServiceResponse
import groovy.util.logging.Slf4j

/**
 * Helper class for Harvester Node API operations
 * Purpose: Provides high-level API methods for Harvester node operations to build ComputeServer models
 * Author: Generated by GitHub Copilot
 * Date: August 25, 2025
 */
@Slf4j
class NodeApiHelper {
    // Instance fields for configuration
    private ComputeServerGroup serverGroup
    private HarvesterApiClient apiClient

    /**
     * Create instance with ComputeServerGroup credentials
     * @param serverGroup ComputeServerGroup containing credentials
     */
    NodeApiHelper(ComputeServerGroup serverGroup = null) {
        this.serverGroup = serverGroup
        this.apiClient = new HarvesterApiClient(serverGroup)
        log.debug "Initialized NodeApiHelper with authentication"
    }

    def getNodes() {
        def ret = [success: true, nodes: []]
        ServiceResponse response = apiClient.get(HarvesterConstants.HARVESTER_API_V1_NODES)

        if (response.success == true) {
            // Fetch metrics for all nodes
            def metricsMap = getNodesMetrics()

            def nodes = response.data?.items ?: []
            nodes.each { node ->
                def nodeName = node.metadata?.name
                def nodeMetrics = metricsMap[nodeName]

                def nodeData = [
                    // Basic metadata
                    uid: node.metadata?.uid,
                    name: nodeName,

                    // Node status
                    ready: isNodeReady(node.status?.conditions),

                    // System information
                    status: node.status,

                    // Resource capacity (parsed using CommonParser utility methods)
                    cpuCapacity: CommonParser.parseCpuValue(node.status?.capacity?.cpu),
                    memoryCapacity: CommonParser.parseMemoryValue(node.status?.capacity?.memory),
                    storageCapacity: CommonParser.parseMemoryValue(node.status?.capacity?.'ephemeral-storage'),

                    // Resource usage (from metrics API)
                    cpuUsage: nodeMetrics?.cpuUsage ?: 0,
                    memoryUsage: nodeMetrics?.memoryUsage ?: 0,

                    // Network addresses
                    internalIP: getNodeInternalIP(node.status?.addresses),
                    externalIP: getNodeExternalIP(node.status?.addresses),
                    hostname: getNodeHostname(node.status?.addresses),

                    // Node type and role (processed)
                    nodeType: getNodeType(node.metadata?.labels),
                    roles: getNodeRoles(node.metadata?.labels)
                ]

                ret.nodes << nodeData
            }
            ret.success = true
            log.info("Fetched ${ret.nodes.size()} nodes from Harvester")
        } else {
            log.error("Failed to fetch nodes from Harvester: ${response.msg}," +
                    " errorCode:${response.errorCode}, statusCode:${response.statusCode}")
            ret.success = false
            ret.message = response.msg ?: 'Failed to fetch nodes from Harvester'
        }
        return ret
    }

    def getMasterNodeDetails() {
        def nodesResult = getNodes()
        if (nodesResult.success) {
            def masterNode = nodesResult.nodes.find { it.nodeType == HarvesterConstants.NODE_TYPE_MASTER }
            if (masterNode) {
                log.info("Master node details: ${masterNode}")
                return masterNode
            } else {
                log.warn("No master node found in the cluster")
            }
        } else {
            log.error("Failed to retrieve master node details: ${nodesResult.message}")
        }
    }

    /**
     * Fetch metrics for all nodes from the metrics API
     * @return Map with node names as keys and metrics data as values
     */
    private Map<String, Map> getNodesMetrics() {
        def metricsMap = [:] as Map<String, Map>
        ServiceResponse response = apiClient.get(HarvesterConstants.HARVESTER_API_V1_NODES_METRICS)

        if (response.success == true) {
            def metricsItems = response.data?.items ?: []
            metricsItems.each { nodeMetric ->
                def nodeName = nodeMetric.metadata?.name
                if (nodeName) {
                    metricsMap[nodeName as String] = [
                        cpuUsage: CommonParser.parseCpuValue(nodeMetric.usage?.cpu),
                        memoryUsage: CommonParser.parseMemoryValue(nodeMetric.usage?.memory)
                    ] as Map
                }
            }
            log.debug("Fetched metrics for ${metricsMap.size()} nodes")
        } else {
            log.warn("Failed to fetch node metrics from Harvester: ${response.msg}. " +
                    "Metrics may not be available. ErrorCode: ${response.errorCode}, StatusCode: ${response.statusCode}")
        }

        return metricsMap
    }

    /**
     * Helper method to determine if a node is ready
     */
    private static boolean isNodeReady(List conditions) {
        if (!conditions) return false

        def readyCondition = conditions.find { it.type == 'Ready' }
        return readyCondition?.status == 'True'
    }

    /**
     * Helper method to extract internal IP from node addresses
     */
    private static String getNodeInternalIP(List addresses) {
        if (!addresses) return null

        def internalIPAddress = addresses.find { it.type == 'InternalIP' }
        return internalIPAddress?.address
    }

    /**
     * Helper method to extract external IP from node addresses
     */
    private static String getNodeExternalIP(List addresses) {
        if (!addresses) return null

        def externalIPAddress = addresses.find { it.type == 'ExternalIP' }
        return externalIPAddress?.address
    }

    /**
     * Helper method to extract hostname from node addresses
     */
    private static String getNodeHostname(List addresses) {
        if (!addresses) return null

        def hostnameAddress = addresses.find { it.type == 'Hostname' }
        return hostnameAddress?.address
    }

    /**
     * Helper method to determine node roles from labels
     */
    private static List<String> getNodeRoles(Map labels) {
        if (!labels) return []

        def roles = []
        labels.each { key, value ->
            if (key.startsWith('node-role.kubernetes.io/')) {
                def role = key.substring('node-role.kubernetes.io/'.length())
                if (role) {
                    roles << role
                }
            }
        }
        return roles
    }

    /**
     * Helper method to determine node type (master, worker, etc.)
     */
    private static String getNodeType(Map labels) {
        if (!labels) return 'worker'

        def roles = getNodeRoles(labels)
        if (roles.contains('master') || roles.contains('control-plane')) {
            return 'master'
        } else if (roles.contains('infra') || roles.contains('infrastructure')) {
            return 'infra'
        } else {
            return 'worker'
        }
    }
}
